import type { FileDiff } from './review';
import { readJson, writeJson } from './storage';

/** Files skipped in review: by path pattern, or by a text the diff contains (e.g. "<auto-generated>"). */
export type IgnoreRules = { paths: string[]; contents: string[] };

const KEY = 'mr-tinder:ignore';
export const loadIgnore = (): IgnoreRules => readJson<IgnoreRules>(KEY) ?? { paths: [], contents: [] };
export const saveIgnore = (rules: IgnoreRules) => writeJson(KEY, rules);

const escape = (s: string) => s.replace(/[.+^${}()|[\]\\]/g, '\\$&');

/**
 * A pattern with `*` / `?` is a glob matched against the whole path or the file name
 * (`*.meta`, `Assets/Generated/*`); without them it matches any part of the path. Case-insensitive.
 */
function pathMatches(path: string, pattern: string) {
  if (!/[*?]/.test(pattern)) return path.toLowerCase().includes(pattern.toLowerCase());
  const re = new RegExp(`^${escape(pattern).replace(/\*/g, '.*').replace(/\?/g, '.')}$`, 'i');
  return re.test(path) || re.test(path.split('/').pop()!);
}

/** The rule that skips the file, or null when it should be reviewed. */
export function ignoredBy(file: FileDiff, rules: IgnoreRules): string | null {
  const path = file.new_path || file.old_path;
  const byPath = rules.paths.find((p) => pathMatches(path, p) || (file.old_path !== path && pathMatches(file.old_path, p)));
  if (byPath) return byPath;
  return rules.contents.find((c) => file.diff.includes(c)) ?? null;
}
